state.airTravel??={month:'all',selected:'june-tiger',parking:'you-out',days:4,share:1,holiday:false,extraDay:false,oil:0,toll:0};
const flightView=document.createElement('section');flightView.id='flights-view';flightView.hidden=true;flightView.innerHTML=`<div class="greeting"><div><div class="eyebrow">FROM YOUR DOOR TO BUSAN</div><h1>機票與桃園停車</h1><p>含托運的來回機票，加上四天停車，一起算清楚。</p></div><button class="outline" data-go="home">回總覽</button></div><div class="flight-route-banner"><span>TPE<small>桃園國際機場</small></span><div>✈<small>直飛・來回・托運</small></div><span>PUS<small>釜山金海機場</small></span></div><div class="flight-brief"><span>2027 年 2–6 月彈性出發</span><span>先沿用 4 天 3 夜</span><span>每位成人比價・人數可調</span></div><div class="flight-disclosure">查價快照：2026/11/13（臺北時間）。已實查 3/9–3/12、5/9–5/12、6/1–6/4 三組，並非掃描 2–6 月所有日期。價格來自 Skyscanner「直飛＋托運行李」結果；不是即時庫存，尚未付款或訂位。15kg 與 20kg 不同，行李重量、退改、手續費以結帳頁為準。</div><div class="flight-tabs"><button class="active" data-air-tab="tickets">✈ 機票推薦</button><button data-air-tab="parking">P 桃園停車</button><button data-air-tab="booking">訂購網站 ↗</button></div><section id="air-tickets"><div class="section-head"><h2>先選適合你的航班</h2><select id="flight-month" aria-label="篩選已查航班月份"><option value="all">所有已查方案</option><option value="03">2027 年 3 月</option><option value="05">2027 年 5 月</option><option value="06">2027 年 6 月</option></select></div><div id="flight-recommendation"></div><div id="flight-quotes"></div><p class="source-note">來源：<a href="https://www.skyscanner.com.tw/routes/tpet/pus/taipei-to-gimhae-international.html" target="_blank" rel="noopener">Skyscanner 桃園／台北－釜山</a>。每張卡片附精確來回日期的重新查價入口；多位成人可能沒有同價位機位，不直接將單人價格當作團體報價。</p></section><section id="air-parking" hidden><div class="section-head"><h2>開車到桃園，停四天</h2><button class="text" id="parking-settings">調整試算 ↗</button></div><div class="parking-summary" id="parking-summary"></div><p class="flight-disclosure">以下使用 2026/11/13 查到的現行費率，2027 年適用價格與名額待業者確認。試算的「4 天」指 4 個計費日；若凌晨出門或回程取車跨午夜，可能多算一天。各場計日方式不同，請提供實際入出場時間詢價。</p><div id="parking-lots"></div><a class="airport-official" href="https://web.taoyuan-airport.com/driving" target="_blank" rel="noopener">桃園機場官方：開車路線、停車場與即時車位 ↗</a></section><section id="air-booking" hidden><div class="section-head"><h2>比價後，核對官網總價</h2></div><div id="booking-sites"></div><p class="source-note">這些按鈕會開啟外部比價／訂購網站，部分網站須重新輸入日期與人數。本站不出售機票、不代收款，也未串接即時票價 API。</p></section><div class="air-total-card"><small>機票＋開車到機場・規劃試算</small><div id="air-total"></div><p id="air-total-note"></p><button class="text" id="air-budget-settings">調整停車、人數及油資 ↗</button></div>`;$('footer').before(flightView);
const flightEntry=document.createElement('button');flightEntry.className='flight-entry';flightEntry.dataset.go='flights';flightEntry.innerHTML='<span>✈</span><div><small>BEFORE YOUR BUSAN DAYS</small><strong>機票推薦 × 桃園四天停車</strong><p>桃園出發・含托運比價・停車費一起算</p></div><b>↗</b>';$('#home-view .trip-strip').after(flightEntry);
