function flightSearchUrl(q){return `https://www.skyscanner.com.tw/transport/flights/tpe/pus/${q.start.slice(2).replaceAll('-','')}/${q.end.slice(2).replaceAll('-','')}/?adults=1&adultsv2=1&cabinclass=economy&rtn=1&preferdirects=true&fare-attributes=checked-bag`}
function flightStay(q){return Math.round((new Date(q.end+'T'+q.back+':00+09:00')-new Date(q.start+'T'+q.arrive+':00+09:00'))/3600000*10)/10}
function parkingMath(lot){let a=state.airTravel,count=a.days+(a.extraDay?1:0),rate=a.holiday?lot.holiday:lot.rate;if(rate===null)return {total:null,count,rate:null};return {total:rate*Math.max(count,lot.id==='pingan-out'?3:1),rate,count}}
function flightCard(q){let selected=state.airTravel.selected===q.id;return `<article class="flight-card ${selected?'selected':''}"><div class="flight-card-head"><span>${q.tag}</span><small>${q.start} → ${q.end}</small></div><h3>${q.airline}<span>往返直飛</span></h3><div class="flight-times"><div><small>去程 TPE → PUS</small><strong>${q.out} <i>→</i> ${q.arrive}</strong></div><div><small>回程 PUS → TPE</small><strong>${q.back} <i>→</i> ${q.land}</strong></div></div><p class="flight-bag">▣ ${q.bag}</p><details><summary>時段、行李與查價提醒</summary><p>${q.note}</p><p>在韓停留約 ${flightStay(q)} 小時，尚未扣除入境、接駁與報到時間。所有起降時間均為當地時間。退改完整條款尚未核實。</p></details><div class="flight-price"><div><small>每位成人・來回・含稅及結果列示托運</small><strong>NT$ ${money(q.price)} <span>起</span></strong></div><span>查價快照</span></div><div class="flight-card-actions"><a class="outline" href="${flightSearchUrl(q)}" target="_blank" rel="noopener">重新查價 ↗</a><button class="primary" data-pick-flight="${q.id}">${selected?'✓ 已選作試算':'選作預算比較'}</button></div><button class="text" data-use-flight-date="${q.id}">套用這組旅行日期 ↗</button></article>`}
function renderAir(){let a=state.airTravel,lot=parkingLots.find(p=>p.id===a.parking)||parkingLots[0],calc=parkingMath(lot),quote=flightQuotes.find(q=>q.id===a.selected)||flightQuotes[0];$('#flight-month').value=a.month;$('#flight-quotes').innerHTML=flightQuotes.filter(q=>a.month==='all'||q.start.slice(5,7)===a.month).map(flightCard).join('');$('#flight-recommendation').innerHTML=`<div class="flight-recommend"><small>目前已查的三組日期中・以價格優先</small><h3>先看 6/1–6/4 台灣虎航</h3><p>每人來回 NT$7,958 起，訂票明細列示 15kg 附加托運。首日晚到，適合把預算留給美食；若想多玩首日白天，同日期華航早到方案約多 NT$2,903。</p><p>需要每程 20kg：本方案仍須加購差額後再比較。2 月、4 月尚未完成同條件查價，不宣稱全期間最低。</p></div>`;$('#parking-summary').innerHTML=`<small>目前試算：${calc.count} 個計費日・${a.share} 人分攤</small><strong>${lot.name}</strong><span>${calc.total===null?'假期費率待詢價':'NT$ '+money(calc.total)+' / 車'}</span>`;$('#parking-lots').innerHTML=parkingLots.map(p=>{let m=parkingMath(p);return `<article class="parking-card ${a.parking===p.id?'selected':''}"><small>${p.type}</small><h3>${p.name}</h3><p class="parking-address">◎ ${p.place}</p><div class="parking-rate"><strong>${m.rate===null?'待詢價':'NT$ '+money(m.rate)}<span> / 日${p.id==='terminal'?'上限':''}</span></strong><span>${m.total===null?'假期費率尚未確認':m.count+' 個計費日約 NT$ '+money(m.total)}</span></div><p>${p.note}</p><div><a class="outline" href="${parkSources[p.source]}" target="_blank" rel="noopener">官方費率／預約 ↗</a><button class="primary" data-pick-parking="${p.id}">${a.parking===p.id?'✓ 已選此停車場':'選作停車試算'}</button></div></article>`}).join('');$('#booking-sites').innerHTML=bookingSites.map(s=>`<a class="booking-link" href="${s.url}" target="_blank" rel="noopener"><div><small>${s.type}</small><h3>${s.name}</h3><p>${s.desc}</p></div><span>↗</span></a>`).join('');let extras=calc.total===null?null:(calc.total+a.oil+a.toll)/a.share;$('#air-total').innerHTML=`<div><small>機票 / 成人</small><strong>NT$ ${money(quote.price)}</strong></div><div><small>停車＋油資路費 / 人</small><strong>${extras===null?'待詢價':'NT$ '+money(Math.ceil(extras))}</strong></div><div><small>規劃合計 / 人</small><strong>${extras===null?'待確認':'NT$ '+money(Math.ceil(quote.price+extras))}</strong></div>`;$('#air-total-note').textContent=`${quote.start}–${quote.end}・${quote.airline}。${calc.count} 個停車計費日，${a.share} 人分攤一台車；油資 NT$${money(a.oil)}、國道路費 NT$${money(a.toll)} 為手動設定${!a.oil&&!a.toll?'，目前尚未估入':''}。不含韓國食宿；非實際團體訂票總額。`}
const airPriorRender=render;render=function(){airPriorRender();renderAir();if(view==='flights')$('#view-label').textContent='機票與桃園停車'};
function parkingSettings(){let a=state.airTravel;modal(`<h2>四天停車與分攤試算</h2><form id="parking-form"><label>停車計費日數<input type="number" name="days" min="1" max="30" value="${a.days}" required></label><label>分攤這一台車的人數<input type="number" name="share" min="1" max="9" value="${a.share}" required></label><label class="check-label"><input type="checkbox" name="holiday" ${a.holiday?'checked':''}> 套用業者連續假期費率</label><label class="check-label"><input type="checkbox" name="extraDay" ${a.extraDay?'checked':''}> 預留跨午夜多一天停車費</label><label>來回油資／整車（新臺幣）<input type="number" name="oil" min="0" max="99999" value="${a.oil}" required></label><label>來回國道路費／整車（新臺幣）<input type="number" name="toll" min="0" max="99999" value="${a.toll}" required></label><p>目前先用四個計費日，實際日數請依停車場的曆日或滿24小時規則及入出場時間確認。2027價格需另向業者核對。</p><button class="primary">更新試算</button></form>`);$('#parking-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);Object.assign(state.airTravel,{days:+f.get('days'),share:+f.get('share'),holiday:f.has('holiday'),extraDay:f.has('extraDay'),oil:+f.get('oil'),toll:+f.get('toll')});persist();close();toast('停車與每人分攤金額已更新')}}
$('#parking-settings').onclick=parkingSettings;$('#air-budget-settings').onclick=parkingSettings;$('#flight-month').onchange=e=>{state.airTravel.month=e.target.value;persist()};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.airTab){$$('[data-air-tab]').forEach(x=>x.classList.toggle('active',x===b));['tickets','parking','booking'].forEach(id=>$('#air-'+id).hidden=id!==d.airTab)}if(d.pickFlight){state.airTravel.selected=d.pickFlight;persist();toast('已更新機票＋停車試算')}if(d.pickParking){state.airTravel.parking=d.pickParking;persist();toast('已更新停車試算')}if(d.useFlightDate){let q=flightQuotes.find(x=>x.id===d.useFlightDate);modal(`<h2>套用 ${q.start} 出發？</h2><p>四日行程日期會更新。去程 ${q.out} 起飛、${q.arrive} 抵達釜山；回程 ${q.back} 自釜山起飛。景點及餐食時間需要依航班另外調整，並未完成訂票。</p><button class="primary" id="confirm-flight-dates">更新旅行日期</button>`);$('#confirm-flight-dates').onclick=()=>{state.start=q.start;state.airTravel.selected=q.id;persist();close();toast('日期已更新，請調整首末日的景點與用餐時間')}}});renderAir();
